window.PRACTICE_CONCEPTS = [{"id": "concept-1", "family": "syllabus", "title": "CIA from a changed incident", "topic": "Unit 1 / CIA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "An attacker reads student records, changes grades, and encrypts the portal database so users cannot log in. Identify the CIA impact of each action. Suggest one distinct control for each objective.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Reading private records harms confidentiality: protect access, minimize exposed data and use appropriate encryption.", "Changing grades harms integrity: enforce authorization, validate updates and use protected audit records or appropriate integrity checks.", "Preventing service use harms availability: maintain tested recovery, resilience and incident-response capability.", "One incident may affect several CIA objectives; distinguish the described actions instead of forcing one label.", "Encryption of stored data does not stop a compromised application with legitimate decryption access from reading it."], "transfer": "If the scenario says only data theft, do not invent a service outage. If it describes deleted backups as well as encryption, explain why recovery and availability are more severely affected.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-2", "family": "syllabus", "title": "Threat, vulnerability and attack surface", "topic": "Unit 1 / CIA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A public login endpoint has unlimited password attempts, a reused administrator password, and an outdated server. Distinguish threat, vulnerability, attack surface, and risk. Give two useful controls.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Threat: an actor or event capable of harm, such as credential guessing or exploitation.", "Vulnerability: a weakness, such as unlimited attempts, credential reuse or unpatched software.", "Attack surface: reachable interfaces and exposure, including the public endpoint and server services.", "Risk combines likelihood and consequences in this context; a weakness is not itself the complete risk assessment.", "Controls include suitable MFA, throttling and detection for guessing, unique protected credentials, and timely tested patches. Identify which weakness each control addresses."], "transfer": "If the interface becomes internal, attack surface and exposure change, but insider threats and compromised accounts can remain. Reassess likelihood without claiming that internal means safe.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-3", "family": "syllabus", "title": "Incident analysis without invented facts", "topic": "Unit 1 / CIA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A report states that an authentication-bypass flaw gave an outsider administrator access. It does not say whether data was copied, changed or disrupted. Explain the possible CIA impacts, the evidence needed, and immediate response priorities.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Administrator access can expose confidential records, permit unauthorized modifications and enable disruption.", "Those are possible impacts, not proven outcomes: separate access gained from actions actually observed.", "Look for protected authentication, application, data-access and change records, plus system or service evidence.", "Contain exposed vulnerable systems as appropriate, preserve evidence and deploy the validated patch or mitigation.", "Review compromised sessions and credentials, check for persistence or unauthorized changes, and restore verified service. Patching alone does not prove an existing compromise has been removed."], "transfer": "When a question supplies confirmed exfiltration, modification or outage, connect those facts directly to CIA. When evidence is missing, state the uncertainty.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-4", "family": "syllabus", "title": "Data at rest, in motion and in process", "topic": "Cryptography role", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A service has encrypted disks and HTTPS, but its application is compromised while processing decrypted customer data. Explain what each encryption layer protects and why the application can still expose plaintext. Outline TEE, homomorphic encryption and MPC.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["At rest: storage encryption protects stored bytes under its key and access assumptions.", "In motion: transport encryption protects communication between its endpoints, not plaintext inside the endpoints.", "In process: ordinary software usually decrypts before computation; a compromised authorized application can access that plaintext.", "A TEE seeks to isolate computation and memory subject to hardware and implementation assumptions. Homomorphic encryption allows supported operations on ciphertext without exposing input plaintext to the processor.", "Secure multiparty computation distributes a computation among parties while limiting input disclosure. These are distinct approaches with different assumptions, not a guarantee supplied by disk or network encryption."], "transfer": "If only a stolen powered-off disk is described, focus on storage and keys. If the endpoint is compromised, discuss endpoint/plaintext exposure. No homomorphic algorithm derivation is needed.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-5", "family": "syllabus", "title": "A hybrid system from first principles", "topic": "Cryptography role", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Design the outline of a confidential channel between parties that have not yet shared a secret. Explain the complementary roles of asymmetric and symmetric cryptography, authentication, and integrity protection.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Use an authenticated asymmetric key-establishment mechanism, such as an authenticated DH-based exchange, or a suitable public-key encapsulation scheme.", "Derive session key material through a specified KDF from the established secret.", "Use efficient symmetric authenticated encryption for bulk application data.", "Authenticate peer keys or the exchange using a trusted mechanism; bare DH alone permits a man-in-the-middle attack.", "Separate key establishment, data confidentiality and integrity/authentication. The outline does not require PKI infrastructure for this syllabus."], "transfer": "If the problem gives an existing pre-shared key, key establishment may change. If large files are involved, do not propose encrypting the entire file with textbook RSA.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-6", "family": "syllabus", "title": "Map primitives to security services", "topic": "Cryptography role", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "For encryption, an unkeyed hash, a MAC and a digital signature, explain confidentiality, integrity/origin assurance and non-repudiation. State the assumptions needed to avoid misleading yes/no claims.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Encryption is intended to hide plaintext; encryption alone does not necessarily detect unauthorized modification.", "A hash fingerprints bytes. It supports an integrity check when the reference digest is independently trusted; an attacker can otherwise replace both message and digest.", "A secure MAC uses a shared secret to authenticate data relative to the holders of that secret; it does not hide the message.", "A digital signature is generated with a private signing key and verified with the public key, supporting integrity, origin assurance and third-party-verifiable evidence.", "Shared-key MACs lack non-repudiation because the verifier can also generate them. Signature evidence depends on trustworthy key attribution and protection; neither a MAC nor an ordinary signature automatically gives freshness."], "transfer": "If a construction combines encryption and authentication, analyze the combined construction. Never credit bare encryption with integrity simply because ciphertext is unreadable.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-7", "family": "syllabus", "title": "Draw AES-128 encryption", "topic": "Ciphers & hashes", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Draw the AES-128 encryption outline, showing the state width, original key width, initial operation, ordinary round operations, final-round difference, and number of rounds.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Input: a 16-byte / 128-bit block arranged as a 4 by 4 byte state; original key: 128 bits.", "Perform initial AddRoundKey using K0 before the numbered rounds.", "Rounds 1–9: SubBytes, ShiftRows, MixColumns, AddRoundKey.", "Round 10: SubBytes, ShiftRows, AddRoundKey; omit MixColumns.", "Key expansion provides 11 round keys including K0. Output is one 128-bit ciphertext block. AddRoundKey is XOR; field operations are not ordinary arithmetic modulo 256."], "transfer": "If AES-192 or AES-256 is substituted, keep the 128-bit block and change original key size, key expansion, and rounds to 12 or 14. Each round key still spans one 128-bit state.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-8", "family": "syllabus", "title": "AES forward and inverse operations", "topic": "Ciphers & hashes", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Explain how AES decryption undoes byte substitution, row shifting, column mixing and key addition. Give the ordinary AES-128 inverse-cipher round order.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["InvSubBytes reverses the bijective S-box lookup.", "InvShiftRows rotates rows right by 0, 1, 2 and 3 byte positions.", "InvMixColumns applies the inverse matrix over GF(2^8); AddRoundKey is its own inverse because repeating the same XOR cancels it.", "Start ciphertext with AddRoundKey K10. For rounds r = 9 down to 1: InvShiftRows, InvSubBytes, AddRoundKey Kr, InvMixColumns.", "Finish with InvShiftRows, InvSubBytes, AddRoundKey K0, without InvMixColumns. Equivalent inverse implementations can reorganize operations with transformed keys; do not mix their order with this ordinary sequence."], "transfer": "If the question supplies a byte for S-box lookup, split its two hex digits into row and column. For column multiplication, use the specified field polynomial and XOR addition.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-9", "family": "syllabus", "title": "DES round widths", "topic": "Ciphers & hashes", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Draw the DES round function F and show every input/output width. Explain the supplied key width versus effective key width and the role of subkeys.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["DES has a 64-bit data block split into two 32-bit halves and 16 Feistel rounds.", "The supplied key has 64 bits including 8 parity bits; the effective key has 56 bits.", "F takes a 32-bit right half, expands it to 48 bits, and XORs a 48-bit round subkey.", "Eight S-boxes each map 6 bits to 4 bits, yielding 32 bits; the P permutation rearranges those 32 bits.", "The key schedule uses PC-1, rotations of two 28-bit halves, and PC-2 to select each 48-bit subkey. DES is historical; the small effective key is inadequate for modern confidentiality."], "transfer": "If asked for the whole cipher, add initial permutation, round updates, final half swap and inverse permutation. If asked only for F, do not mix key-schedule widths with its data path.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-10", "family": "syllabus", "title": "Why a lossy F can still decrypt", "topic": "Ciphers & hashes", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "A DES S-box maps 6 bits to 4 bits, so it is not invertible. Prove that this does not prevent a Feistel round from being inverted. Contrast the AES structure.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["A forward round is Li = R(i−1), Ri = L(i−1) XOR F(R(i−1),Ki).", "The old right half is retained exactly as Li.", "Recover R(i−1) = Li, then L(i−1) = Ri XOR F(Li,Ki).", "Repeating XOR with the same F output recovers the old left half; F itself never needs inversion.", "AES is a substitution/permutation structure using invertible transformations of the full state, rather than this half-preserving Feistel argument."], "transfer": "If the round function changes but the Feistel update remains the same, the inversion argument still applies. Check the scheme’s exact swap/output convention.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-11", "family": "syllabus", "title": "SHA-256 padding boundaries", "topic": "Ciphers & hashes", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "For messages of 55, 56 and 64 bytes, determine the number of SHA-256 blocks after padding. Explain the marker, zero bytes and length field.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["SHA-256 blocks contain 64 bytes. Append a one bit, represented as byte 80 for byte-aligned input.", "Append zeros until the position before the length field is 56 modulo 64 bytes; append the original bit length in 8 big-endian bytes.", "55 bytes: 55 + 1 marker + 0 zeros + 8 length bytes = 64 bytes, one block.", "56 bytes: 56 + 1 marker + 63 zeros + 8 length bytes = 128 bytes, two blocks.", "64 bytes: 64 + 1 marker + 55 zeros + 8 length bytes = 128 bytes, two blocks. The length field excludes padding."], "transfer": "For any new byte length n, find the smallest multiple of 64 at least n + 9. For non-byte-aligned input, reason in bits instead.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-12", "family": "syllabus", "title": "SHA-256 versus MD5 outlines", "topic": "Ciphers & hashes", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Compare SHA-256 and MD5 by block size, digest size, working state, operation structure and security role. Draw a high-level block-to-digest flow.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Both process 512-bit / 64-byte input blocks after their defined padding.", "MD5 has a 128-bit digest and four 32-bit state words; SHA-256 has a 256-bit digest and eight 32-bit state words.", "MD5 performs 64 operations in four phases with message-word selection and rotations; SHA-256 performs 64 compression rounds with an expanded 64-word schedule.", "Each block updates a chaining state; final serialization gives the digest. These counts describe a single block’s compression, not the whole arbitrary-length message.", "MD5 collision resistance is broken and it is unsuitable for collision-sensitive integrity/signature use. SHA-256 is the taught contemporary hash example; ordinary hashing alone is not sender authentication."], "transfer": "If the message spans multiple blocks, repeat the compression with the updated chain. If asked about HMAC, distinguish the keyed construction from properties of an ordinary unkeyed hash.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-13", "family": "syllabus", "title": "Three hash resistance requirements", "topic": "Ciphers & hashes", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Distinguish preimage, second-preimage and collision resistance. Give one exam-style problem statement for each and their ideal generic work factors for an n-bit digest.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Preimage: given y, find any M with H(M) = y; ideal generic work is about 2^n evaluations.", "Second preimage: given M, find different M′ with H(M′) = H(M); for ordinary short-message ideal reasoning, about 2^n.", "Collision: find any distinct pair M, M′ with equal digests; ideal birthday work is about 2^(n/2).", "The given input distinguishes the three tasks: target digest, target message, or no fixed target.", "Finite output space means collisions exist for unrestricted input lengths; security requires difficulty finding useful collisions, not mathematical impossibility."], "transfer": "If n changes from 256 to 128, substitute into the relevant exponent. Distinguish ideal generic costs from an attack on a specific weak hash.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-14", "family": "syllabus", "title": "Random oracle model vocabulary", "topic": "Ciphers & hashes", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Describe an ideal random oracle, three essential behaviors, and why it is useful in cryptographic proofs. State its limitation as a model.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["It is a public function interface assigning a uniformly random output in a fixed output space to each new input.", "Consistency: repeated identical inputs return the same output.", "Freshness/randomness: a previously unqueried input receives an independently sampled output.", "Global access: all parties querying the same oracle see one consistent input/output mapping. Random outputs need not be distinct; collisions remain possible.", "It supports idealized proof reasoning about hash-based schemes. A concrete hash is a deterministic algorithm and is not literally a random oracle; an ideal-model proof does not by itself prove every real instantiation secure."], "transfer": "If the teacher phrases the three properties as determinism, uniformity and independence, connect them to these same behaviors. Do not replace independence with collision-free output.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-15", "family": "syllabus", "title": "HMAC key and outer-input length", "topic": "Authentication / MACs", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "For HMAC-SHA-256, normalize keys of 4, 64 and 65 bytes. State the ipad/opad values, inner formula and outer formula, and the outer input length before hash padding.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["B = 64 bytes and digest width L = 32 bytes. A 4-byte key gets 60 zero bytes; a 64-byte key is kept unchanged.", "A 65-byte key is hashed to 32 bytes, then zero-padded with 32 bytes to make K0 of length 64.", "ipad is byte 36 repeated 64 times; opad is byte 5c repeated 64 times. They are public constants XORed with K0.", "I = H((K0 XOR ipad) || M); T = H((K0 XOR opad) || I).", "The outer input is 64 + 32 = 96 raw bytes before SHA-256’s internal padding. Do not append the 64 characters of the displayed hex digest."], "transfer": "If SHA-512 replaces SHA-256, use the new block and digest widths. If the key equals the block width exactly, it is not hashed in key normalization.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-16", "family": "syllabus", "title": "CMAC final-block cases", "topic": "Authentication / MACs", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "For AES-CMAC messages of 0, 16, 17 and 32 bytes, state the number of processing blocks, whether padding is used, and which final-block subkey is used. Explain where K1 and K2 come from.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["0 bytes: one effective block, 80 followed by fifteen 00 bytes, XOR K2.", "16 bytes: one full block, no padding, XOR K1. 32 bytes: two full blocks, modify only the final one with K1.", "17 bytes: two blocks; final block is one message byte, then 80 and fourteen 00 bytes, XOR K2.", "L = AES_K(0^128), K1 = dbl(L), K2 = dbl(K1); doubling shifts the whole 128-bit word left and XORs 00...87 if its original highest bit was one.", "Start X0 = zero and chain Xi = AES_K(X(i−1) XOR effective block i). Every AES uses original K; K1/K2 mask only the ending. The last state is the tag."], "transfer": "For any new length, test whether the original length is positive and divisible by 16. Padding a partial block does not move it to the K1 case.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-17", "family": "syllabus", "title": "MAC versus digital signature", "topic": "Authentication / MACs", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Alice and Bob share a MAC key. Bob shows a tagged message to a third party and claims it proves Alice sent it. Analyze the claim and contrast digital-signature verification.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["A matching MAC supports integrity and origin relative to holders of the shared secret.", "Bob also has that secret and can generate the same tag, so the third party cannot identify Alice as the creator merely from the MAC.", "A signature is generated with a private signing key and verified with the corresponding public verification key.", "A verifier does not need the private signing key, making third-party verification and non-repudiation support possible under key-attribution and key-protection assumptions.", "Neither primitive by itself encrypts the message or proves freshness. Signatures are not universally implemented as raw RSA private-key encryption."], "transfer": "If multiple people share K, origin assurance concerns that whole set. If a signing private key is shared or compromised, explain why attribution weakens.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-18", "family": "syllabus", "title": "Textbook RSA is not a complete secure scheme", "topic": "RSA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Explain why RSA formulas alone are insufficient for a deployed encryption or signature system. State the appropriate role of encoding/padding and distinguish encryption from signing.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Textbook encryption is c = m^e mod n and decryption is m = c^d mod n; real message encoding must satisfy the representative domain.", "Bare textbook RSA is deterministic and algebraically malleable, so those formulas alone do not provide modern confidentiality against active attacks.", "RSA encryption uses a specified encoding/padding scheme, for example OAEP, in an appropriate protocol.", "RSA signatures use a specified signature encoding, for example PSS, with a signing/verification algorithm; a signature is not simply a generic message encrypted with a private key.", "Key sizes, randomness, validation and protocol use matter. These scheme names are conceptual depth around the syllabus outline, not a request to derive their full encoding algorithms."], "transfer": "If asked only for a small numerical textbook exercise, perform its arithmetic and label it a toy illustration. If asked about deployment, include the missing scheme and protocol assumptions.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-19", "family": "syllabus", "title": "Diffie–Hellman with changed values", "topic": "DH / number theory", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "For prime p = 23, generator g = 5, Alice scalar a = 6 and Bob b = 15, calculate public values A and B and the shared residue. Explain the correctness identity.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["A = 5^6 mod 23 = 8; B = 5^15 mod 23 = 19.", "Alice calculates B^a mod 23 = 19^6 mod 23 = 2.", "Bob calculates A^b mod 23 = 8^15 mod 23 = 2.", "Both expressions equal g^(ab) mod p because (g^b)^a = (g^a)^b.", "The residue is shared secret material; a real protocol derives keys through a KDF and authenticates the exchange. Tiny values illustrate arithmetic, not practical security."], "transfer": "If public values are supplied, do not recompute a private exponent using a guessed inverse. Compute the peer’s public value raised to your own private scalar.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-20", "family": "syllabus", "title": "DH assumptions and man-in-the-middle", "topic": "DH / number theory", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Define DLP, computational DH and decisional DH in a cyclic group. Explain why bare DH is vulnerable to a man-in-the-middle even if the computational problem is hard.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["DLP: given g and g^a, recover exponent a modulo the group order.", "CDH: given g, g^a and g^b, compute g^(ab).", "DDH: distinguish (g, g^a, g^b, g^(ab)) from a tuple with an independent random fourth element in the relevant group.", "Hardness assumptions depend on the selected group; do not assert that all three problems are identical.", "A man-in-the-middle replaces public values and runs separate exchanges with each endpoint, without solving the original CDH instance. Authenticate the exchanged public values/transcript or use an authenticated key-establishment protocol."], "transfer": "For elliptic curves, replace exponentiation by scalar multiplication: P, aP, bP, abP. Correctness and authentication are separate questions.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-21", "family": "syllabus", "title": "Modular inverses when the modulus changes", "topic": "DH / number theory", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Find 17^(-1) mod 43 using the extended Euclidean algorithm. Decide whether 6^(-1) mod 21 exists. Explain why exponentiation shortcuts have conditions.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["43 = 2×17 + 9; 17 = 1×9 + 8; 9 = 1×8 + 1.", "Back-substitute: 1 = 9 − 8 = 2×9 − 17 = 2×43 − 5×17.", "Therefore 17^(-1) mod 43 = −5 mod 43 = 38; check 17×38 = 646 ≡ 1.", "gcd(6,21) = 3, so no inverse exists: 6x cannot be congruent to 1 modulo 21.", "For prime p and nonzero a, inverse = a^(p−2) mod p. More generally Euler gives a^(φ(n)−1) when gcd(a,n) = 1; computing φ(n) may itself require factorization. Extended Euclid needs no prime-modulus assumption."], "transfer": "If the denominator shares a factor with the modulus, do not invent an inverse. In ECC over a prime field, first handle zero-denominator group cases.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-22", "family": "syllabus", "title": "Euler theorem and exponent reduction", "topic": "DH / number theory", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Use Euler’s theorem to calculate 23^62 mod 33. State its condition and explain how Fermat is a prime-modulus special case.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["33 = 3×11 and φ(33) = (3−1)(11−1) = 20.", "gcd(23,33) = 1, so Euler gives 23^20 ≡ 1 mod 33.", "62 = 3×20 + 2, hence 23^62 ≡ 23^2 mod 33.", "23^2 = 529 = 16×33 + 1, so the answer is 1.", "Euler states a^φ(n) ≡ 1 mod n for coprime a,n. When n = prime p, φ(p) = p−1 and the familiar Fermat result follows. A non-coprime base cannot use this reduction blindly."], "transfer": "If the modulus is p^k, φ(p^k) = p^(k−1)(p−1). If it is a product of distinct primes, multiply their p−1 factors.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-23", "family": "syllabus", "title": "Orders and generators", "topic": "DH / number theory", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Find the order of every element in the multiplicative group Z7*. Identify its generators and explain why the group is abelian.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["The elements are 1,2,3,4,5,6 with multiplication modulo 7.", "Orders: ord(1)=1; ord(2)=3 since 2,4,1; ord(3)=6 since 3,2,6,4,5,1.", "ord(4)=3 since 4,2,1; ord(5)=6 since 5,4,6,2,3,1; ord(6)=2 since 6,1.", "Generators are 3 and 5 because their powers visit all six elements before returning to identity.", "Multiplication is closed and associative, 1 is identity, every nonzero element has an inverse, and multiplication commutes. Commutativity makes this group abelian."], "transfer": "If the modulus becomes composite, Z_n* contains only residues coprime to n, not every nonzero residue. Not every such group is cyclic.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-24", "family": "syllabus", "title": "Group, ring and field distinctions", "topic": "DH / number theory", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Explain why Z8 is a ring but not a field, while Z7 is a field. Distinguish the additive group of a ring from its nonzero multiplicative elements.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["A ring has an abelian group under addition, associative multiplication and distributivity; the syllabus examples use rings with a multiplicative identity.", "Modulo 8, addition and multiplication obey these operations, but 2×4 = 0 with both factors nonzero.", "The element 2 has no multiplicative inverse modulo 8, so Z8 is not a field.", "Modulo prime 7, every nonzero residue is coprime to 7 and has a multiplicative inverse, so Z7 is a field.", "All ring elements form the additive group. Only units form a multiplicative group in a general ring; in a field every nonzero element is a unit."], "transfer": "If the set or operation changes, state both explicitly. A group under addition does not automatically provide division under multiplication.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-25", "family": "syllabus", "title": "Changing the reduction polynomial", "topic": "Finite fields", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "A student defines a claimed GF(2^4) with reduction polynomial x^4 + x^2 + 1. Show why irreducibility matters by examining the element x^2 + x + 1.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Over GF(2), (x² + x + 1)² = x^4 + x² + 1 because cross terms cancel in characteristic 2.", "The proposed degree-four polynomial factors as a square, so it is reducible.", "In its quotient ring, the nonzero residue x² + x + 1 has square zero.", "A nonzero zero divisor cannot have a multiplicative inverse; therefore this quotient is not a field.", "To obtain GF(2^4), choose an irreducible degree-four polynomial such as x^4 + x + 1. Different valid polynomials change representation-level multiplication results."], "transfer": "If a new polynomial is supplied, do not reuse x^4 = x + 1 from the original sheet. Validate the field definition when the question asks you to critique it.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-26", "family": "syllabus", "title": "Validate ECC input before arithmetic", "topic": "ECC / ECDH", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "On y² ≡ x³ + 2x + 2 mod 17, a proposed base point is R = (5,2). Is it valid? What should you do before computing 2R or an ECDH public key?", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["For R, y² = 2² = 4 mod 17.", "The right side is 5³ + 2×5 + 2 = 137 ≡ 1 mod 17.", "Since 4 ≠ 1, R is not on the stated curve. Do not silently apply point formulas as if it were a valid group element.", "Check the field, nonsingularity and point membership; if the source is inconsistent, state the discrepancy or obtain the corrected point.", "For real ECDH, public-point, identity and subgroup checks follow the chosen domain parameters and protocol, and key derivation is needed. This exercise’s small curve is only for hand arithmetic."], "transfer": "If the point or curve coefficients change, repeat the membership test. A result produced by a formula is not proof that invalid inputs belong to the curve.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-27", "family": "syllabus", "title": "ECC zero denominator", "topic": "ECC / ECDH", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "On y² ≡ x³ + 2x + 3 mod 17, verify Q = (16,0) lies on the curve and calculate 2Q. Explain why trying to invert 2y fails.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["At x = 16, x³ + 2x + 3 = 4131 = 243×17, so the right side is zero; y² is also zero.", "The point is its own negative because −0 = 0 in the field.", "Q + (−Q) = O, so 2Q = O, the identity point at infinity.", "The doubling denominator 2y is zero and has no inverse modulo 17. The group-law special case must be handled before the finite slope formula.", "Do not write a finite slope, divide by zero, or confuse O with coordinate pair (0,0)."], "transfer": "If two distinct points have the same x and opposite y values, their sum is also O. If y is nonzero, the ordinary prime-field doubling denominator can be inverted.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-28", "family": "syllabus", "title": "Audit an invalid RSA private exponent", "topic": "RSA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "An exercise gives n = 143 = 11×13, d = 27 and C = 9. Compute 9^27 mod 143, then decide whether d is a valid standard RSA private exponent for those primes.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Repeated squares modulo 143: 9^1=9, 9^2=81, 9^4=126, 9^8=3, 9^16=9.", "27 = 16 + 8 + 2 + 1; 9×3×81×9 mod 143 = 92.", "φ(n)=120 and λ(n)=lcm(10,12)=60. gcd(27,120)=3 and gcd(27,60)=3.", "No public exponent e satisfies ed ≡ 1 modulo λ(n), so d=27 is not a valid standard RSA private exponent for this modulus.", "The modular-power answer 92 is still meaningful. Call it a power calculation under inconsistent RSA parameters, rather than validating the purported key. A corrected example can use d=37, e=13."], "transfer": "If only a power calculation is requested, calculate it but do not assume invalid cryptographic parameters are valid. If key validity is requested, check invertibility modulo the exponent period.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-29", "family": "syllabus", "title": "RSA with a non-coprime message", "topic": "RSA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A toy RSA key uses p=11, q=13, e=7, d=103. Encrypt m=11 and explain why RSA decryption still works even though gcd(m,n) is not 1. Why is direct Euler exponent reduction unsafe here?", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["n=143; φ(n)=120; 7×103=721=1+6×120, so the exponents meet the textbook key relation.", "Encryption: 11^7 mod 143 = 132. Decryption: 132^103 mod 143 = 11.", "The message is not a unit modulo n: gcd(11,143)=11, so Euler’s a^φ(n)=1 statement does not apply to this base.", "Modulo 11 the representative is zero and stays zero. Modulo 13 it is a nonzero field element, so the exponent relation recovers it.", "The prime-modulus results combine by CRT. Correct square-free RSA keys work for all representatives 0≤m<n; this is not a license to apply Euler blindly to a non-coprime base."], "transfer": "If a ciphertext shares a prime factor with n, repeated squaring remains a valid power method. Use CRT reasoning where required instead of unsupported exponent reduction.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-30", "family": "syllabus", "title": "ECB and CBC diagrams and errors", "topic": "Modes / integrity", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Draw ECB and CBC encryption for two blocks. If one ciphertext bit in block C2 flips during transmission, describe the plaintext effects for each mode. Assume correct framing and no authentication check.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["ECB: Ci=E_K(Pi); blocks are independent and equal plaintext blocks reveal equality under the same key.", "CBC: C0=IV and Ci=E_K(Pi XOR C(i−1)); the previous ciphertext feeds the next plaintext XOR.", "For CBC encryption use the scheme’s fresh unpredictable IV requirements; an IV is not another key.", "ECB corruption affects P2 only, unpredictably. CBC corruption makes P2 unpredictable and flips that same bit in P3, if P3 exists; later blocks are unaffected.", "Error propagation is not a tamper-detection guarantee. Use authentication or an appropriate authenticated construction when unauthorized modification must be detected."], "transfer": "If the flipped block is the final block, there is no subsequent plaintext block to affect. If the IV itself is altered in CBC, corresponding bits of the first plaintext block change.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-31", "family": "syllabus", "title": "CFB segment size changes the answer", "topic": "Modes / integrity", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Compare a one-bit substitution error in ciphertext segment C2 for AES-CFB-128 and AES-CFB-8. Show which original plaintext segment flips predictably and how long later corruption can last.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["CFB-s uses Z_i=MSB_s(E_K(R_i)), Ci=Pi XOR Z_i, and R(i+1)=LSB_(128−s)(Ri)||Ci.", "The affected plaintext segment P2 has the same bit flipped, because the incoming ciphertext is directly XORed with its otherwise-correct mask.", "CFB-128: the next segment P3 can be unpredictably corrupted; P4 onward recover with correct framing.", "CFB-8: the bad bit can remain in the 128-bit register for the next 16 byte segments P3…P18; P19 onward recover.", "Corrupted means the difference is unpredictable, not that every bit certainly flips. Bit insertion/deletion is a separate synchronization question."], "transfer": "For a b-bit register and s-bit segments, use up to ceil(b/s) later affected segments. Specify whether a question uses the word block to mean a cipher block or a smaller segment.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-32", "family": "syllabus", "title": "CTR keystream reuse", "topic": "Modes / integrity", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Two equal-length messages are encrypted under the same CTR key with the same counter inputs. Derive the information leaked and explain why a good block cipher does not fix the protocol error.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Both messages use the same mask Z: C=P XOR Z and C′=P′ XOR Z.", "C XOR C′=P XOR P′ because Z XOR Z=0.", "Known plaintext for one message reveals the mask in those positions and therefore the other plaintext bytes in those positions.", "Ensure that no counter block repeats under the same key, including across messages; nonce/counter allocation is a protocol responsibility.", "CTR by itself supplies confidentiality only. An attacker can also cause controlled plaintext bit flips by modifying ciphertext unless an integrity mechanism detects the change."], "transfer": "If nonces change but counter blocks still collide under the encoding, the problem remains. Distinct counter blocks, not merely differently named fields, are required.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-33", "family": "syllabus", "title": "Randomness requirements", "topic": "Authentication / access", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A system generates encryption keys, session secrets and challenges using a predictable counter or time-seeded ordinary PRNG. Explain the problem, the need for a CSPRNG, and why not every IV requires identical properties.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Keys and secret session values need sufficient entropy and unpredictability; an attacker must not predict them from visible values or timing.", "A cryptographically secure generator must be appropriately seeded and used according to the relevant construction’s requirements.", "An ordinary simulation PRNG can have a recoverable state or predictable output and is unsuitable merely because its output looks random.", "Uniqueness and unpredictability are distinct: CTR counter inputs require no repetition under the same key, while CBC encryption requires an unpredictable IV.", "Challenges also need protocol-defined freshness and verification. Random generation alone does not authenticate a party or prevent replay unless the challenge is properly bound and checked."], "transfer": "If asked about a particular mode, state its exact IV/nonce property rather than writing “all IVs must be random”. If key generation changes, re-evaluate entropy and predictability.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-34", "family": "syllabus", "title": "Strong authentication and factors", "topic": "Authentication / access", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "Compare password+PIN, password+one-time token and an appropriately bound hardware authenticator. Identify factor categories, common misconceptions, and one remaining limitation.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Password and PIN are both knowledge factors; two secrets of that category are not two independent factor categories.", "A token or device is a possession factor; combining it with a knowledge factor can provide MFA if implemented correctly.", "Biometrics are an inherence factor; their use needs suitable protection and binding to the actual authentication protocol.", "One-time codes can still be phished or relayed depending on the protocol. Properly bound authenticators can reduce those attacks, but the label “hardware” alone is not the security argument.", "Recovery paths, enrollment, session protection and endpoint compromise remain relevant. Strong authentication does not automatically authorize every operation."], "transfer": "If the question lists two credentials, classify their underlying factors before counting them. If the attacker already controls a session, discuss session and endpoint controls too.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-35", "family": "syllabus", "title": "Authentication, authorization and enforcement", "topic": "Authentication / access", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A student logs in successfully and changes another student’s grade by changing an object identifier. Distinguish authentication, authorization and access control. Explain the failed decision and a suitable permission rule.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Authentication establishes an identity or verifies the claimed credential/context; the login succeeded.", "Authorization determines which actions that identity may perform on which resources.", "Access control enforces the permission decision at the operation/resource boundary.", "The grade-changing action lacks the required authorization; login alone cannot grant authority over another student’s record.", "A rule might permit only authorized teaching staff to update assigned-course grades, with checks on each requested object and protected records of the change. This is an authorization illustration, not a request to study a Unit 3 exploit workflow."], "transfer": "If the user changes their own profile instead, specify allowed fields and object ownership. If role changes, recalculate permissions rather than equating authenticated with permitted.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-36", "family": "syllabus", "title": "DAC, MAC and RBAC", "topic": "Authentication / access", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A file owner shares a file, a classification policy prevents lower-clearance reading, and a registrar role can update enrollments. Identify the access-control models and distinguish them from cryptographic MACs.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Owner-directed permission assignment illustrates discretionary access control (DAC), subject to the system’s policy.", "An enforced label/clearance policy beyond ordinary owner discretion illustrates mandatory access control (MAC).", "Permissions assigned to roles, with users receiving roles, illustrate role-based access control (RBAC).", "Least privilege means granting only the permissions needed for the task; constraints such as separation of duties can limit role combinations or actions.", "Here MAC means Mandatory Access Control; in HMAC/CMAC lessons it means Message Authentication Code. Expand the abbreviation to avoid a category mistake."], "transfer": "If a scenario mixes owner sharing, labels and roles, discuss the combined policy rather than demanding a single exclusive model. A role name alone is not a permission check.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-37", "family": "syllabus", "title": "Privilege escalation", "topic": "Authentication / access", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "A user accesses another user’s records at the same role level, then obtains administrator rights. Distinguish horizontal and vertical privilege escalation and propose controls.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Horizontal escalation crosses to another identity’s or peer resource’s permissions without rising to a higher role level.", "Vertical escalation gains a more privileged role or capability, such as administrator actions.", "Apply operation-level authorization and object-level checks, with suitable identity/resource binding.", "Limit privileges, protect privileged credentials and workflows, patch exploitable weaknesses and monitor relevant changes.", "Identify the actual permission boundary crossed. Successful authentication or a hidden UI element is not an adequate enforcement mechanism."], "transfer": "If only a different object identifier is changed, inspect ownership or allowed scope. If a role or process privilege changes, inspect the higher-privilege boundary.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-38", "family": "syllabus", "title": "Avalanche, diffusion and completeness", "topic": "Ciphers & hashes", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Define confusion, diffusion, avalanche and the cipher completeness effect. Does an avalanche test prove security or imply every output bit changes on every input change?", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Confusion makes relationships between key, data and output complex; diffusion spreads input influence across output positions.", "Avalanche is a statistical design goal: changing one input or key bit should change about half the output bits on average.", "Cipher completeness means every output bit depends functionally on every input bit; dependence can mean a change affects it for some inputs.", "Neither property promises every output bit flips for every trial. An empirical test of some inputs is not a proof covering all inputs or all attacks.", "A design can pass an avalanche check while retaining exploitable structure. Cipher completeness here differs from protocol completeness, where honest participants succeed."], "transfer": "If a question uses “completeness”, identify whether it concerns bit dependence or a protocol property. If it asks about a single observed output, avoid treating the average as a guaranteed exact count.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-39", "family": "syllabus", "title": "One-way and trapdoor functions", "topic": "DH / number theory", "scope": "Supporting", "difficulty": "Standard", "marks": 5, "q": "Define a one-way function and a trapdoor one-way function. Give the modular exponentiation and RSA permutation examples with their assumptions and domains.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["A one-way function is efficient to evaluate but computationally difficult to invert on the relevant input distribution and domain, under an assumption.", "In a suitable cyclic group, a→g^a is easy to evaluate, while recovering a from g^a is the discrete logarithm problem.", "A trapdoor one-way function additionally has secret information enabling efficient inversion.", "For an appropriately generated RSA modulus n and exponent e, x→x^e mod n is a candidate trapdoor permutation under the RSA assumption; the private exponent derived using the factorization enables inversion.", "Do not claim hardness for arbitrary tiny parameters, arbitrary groups or a noninvertible exponent. “One-way” is computational rather than a ban on defining an inverse relation."], "transfer": "If the exponent or domain changes, check whether the function remains a permutation. Factoring is a sufficient route to RSA inversion; avoid asserting unproved equivalence of all associated hardness problems.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}, {"id": "concept-40", "family": "syllabus", "title": "Response priorities and CIA trade-offs", "topic": "Unit 1 / CIA", "scope": "Core", "difficulty": "Standard", "marks": 5, "q": "An organization discovers active exploitation of an unpatched authentication-bypass flaw in an internet-facing service. Explain immediate and longer-term actions and a confidentiality/integrity/availability trade-off.", "hint": "Define the terms, identify the relevant conditions, then justify each step.", "solution": ["Confirm exposure and the vendor-provided affected versions or mitigation, without delaying necessary containment for a fully complete investigation.", "Restrict or isolate the vulnerable service when appropriate and deploy a validated patch or mitigation; this can temporarily affect availability to reduce confidentiality/integrity risk.", "Preserve relevant evidence and investigate unauthorized access, changes, persistence and data exposure.", "Review sessions, credentials and related trust assumptions where compromise is indicated; recover from verified data and test service restoration.", "Improve inventory, patch processes, privilege controls, monitoring and recovery drills. Distinguish a hypothetical scenario analysis from a claim about current incidents."], "transfer": "If the service is critical to immediate operations, discuss controlled containment alternatives and explicit impact. If no active exploitation is known, distinguish prevention from confirmed incident response.", "final": "See the worked reasoning and marking points.", "checklist": ["Terms and conditions are correct", "Method or security objective is identified", "Reasoning supports the answer", "Relevant distinction or limitation is stated", "Answer addresses every requested part"]}];
